public class LogPurgeJob implements Schedulable {
    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        Datetime now = Datetime.now();
        Datetime cutoffNormal = now.addDays(-30);
        Datetime cutoffError = now.addDays(-180);

        List<FB_Integration_Log__c> toDelete = new List<FB_Integration_Log__c>();

        for (FB_Integration_Log__c log : [
            SELECT Id, Level__c, CreatedDate
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :cutoffNormal
            ORDER BY CreatedDate ASC
        ]) {
            if (log.Level__c == 'ERROR') {
                if (log.CreatedDate < cutoffError) {
                    toDelete.add(log);
                }
            } else {
                toDelete.add(log);
            }
        }

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
    }

    public static Id scheduleNightly() {
        String cronExp = '0 0 2 * * ?';
        String jobName = 'Log purge (nightly)';
        return System.schedule(jobName, cronExp, new LogPurgeJob());
    }
}
