public with sharing class Opportunities extends fflib_SObjectDomain
{
	public Opportunities(List<Opportunity> sObjectList)
	{
		super(sObjectList);
	}

	public override void onBeforeInsert()
	{
		// Validation handled in validateBeforeInsert
	}

	public override void onBeforeUpdate(Map<Id, SObject> existingRecords)
	{
		// Validation handled in validateBeforeUpdate
	}

	public override void validateBeforeInsert()
	{
		for (Opportunity record : (List<Opportunity>) Records)
		{
			validateAmountNotNegative(record);
		}
	}

	public override void validateBeforeUpdate(Map<Id, SObject> existingRecords)
	{
		for (Opportunity record : (List<Opportunity>) Records)
		{
			Opportunity oldRecord = (Opportunity) existingRecords.get(record.Id);

			validateAmountNotNegative(record);
			validateAmountImmutableOnWon(record, oldRecord);
		}
	}

	private void validateAmountNotNegative(Opportunity record)
	{
		if (record.Amount != null && record.Amount < 0)
		{
			error('Amount cannot be negative.', record, Opportunity.Amount);
		}
	}

	private void validateAmountImmutableOnWon(Opportunity record, Opportunity oldRecord)
	{
		if (oldRecord == null)
		{
			return;
		}

		if (oldRecord.StageName == 'Closed Won' && record.Amount != oldRecord.Amount)
		{
			error('Amount cannot change on a won opportunity.', record, Opportunity.Amount);
		}
	}

	public class Constructor implements fflib_SObjectDomain.IConstructable
	{
		public fflib_SObjectDomain construct(List<SObject> sObjectList)
		{
			return new Opportunities(sObjectList);
		}
	}
}
