public with sharing class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds AND Phone != null
        ];

        List<Contact> toUpdate = new List<Contact>();
        for (Contact c : contacts) {
            String cleaned = c.Phone.replaceAll('[^0-9+]', '');
            // Only update if something actually changed to avoid unnecessary DML
            if (cleaned != c.Phone && String.isNotBlank(cleaned)) {
                c.Phone = cleaned;
                toUpdate.add(c);
            }
        }

        if (toUpdate.isEmpty()) {
            return failures;
        }

        Database.SaveResult[] results = Database.update(toUpdate, false);
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results[i];
            if (!sr.isSuccess()) {
                failures.put(toUpdate[i].Id, sr.getErrors()[0].getMessage());
            }
        }

        return failures;
    }
}
