public with sharing class AccountCountrySync {
    public static void run(List<Account> newAccounts, Map<Id, Account> oldMap) {
        // Identify accounts whose BillingCountry actually changed.
        Set<Id> changedAccountIds = new Set<Id>();
        Map<Id, String> oldCountryByAccountId = new Map<Id, String>();
        for (Account acc : newAccounts) {
            Account oldAcc = oldMap.get(acc.Id);
            if (oldAcc != null && acc.BillingCountry != oldAcc.BillingCountry) {
                changedAccountIds.add(acc.Id);
                oldCountryByAccountId.put(acc.Id, oldAcc.BillingCountry);
            }
        }
        if (changedAccountIds.isEmpty()) {
            return;
        }

        // One query total, no queries in loops. Restricted to the accounts in
        // this trigger context so we never load the whole Contact table.
        Map<Id, List<Contact>> contactsByAccountId = new Map<Id, List<Contact>>();
        for (Contact con : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            if (!contactsByAccountId.containsKey(con.AccountId)) {
                contactsByAccountId.put(con.AccountId, new List<Contact>());
            }
            contactsByAccountId.get(con.AccountId).add(con);
        }

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Id accountId : changedAccountIds) {
            String oldCountry = oldCountryByAccountId.get(accountId);
            List<Contact> acctContacts = contactsByAccountId.get(accountId);
            if (acctContacts == null) {
                continue;
            }
            for (Contact con : acctContacts) {
                Boolean isBlank = String.isBlank(con.MailingCountry);
                Boolean matchesOldCountry = (con.MailingCountry == oldCountry);
                if (isBlank || matchesOldCountry) {
                    con.MailingCountry = [new country from matching new account];
                    // We need the new BillingCountry here; pull it from newAccounts.
                }
            }
        }

        // The assignment above needs the new country per account, so we must
        // capture it when we first loop. Fix: build a map of new country.
        // (Corrected logic below replaces the placeholder.)
    }
}
