import { LightningElement, track } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const FREE_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    @track fullName = '';
    @track email = '';
    @track company = '';

    handleFullNameChange(event) {
        this.fullName = event.detail.value;
    }

    handleEmailChange(event) {
        this.email = event.detail.value;
    }

    handleCompanyChange(event) {
        this.company = event.detail.value;
    }

    async handleRegister() {
        const emailInput = this.template.querySelector('input[data-field="email"]');
        const fullNameInput = this.template.querySelector('input[data-field="fullName"]');
        const companyInput = this.template.querySelector('input[data-field="company"]');

        // Step 1: validate work email domain before reportValidity
        const emailValue = (this.email || '').trim().toLowerCase();
        const atIndex = emailValue.lastIndexOf('@');
        let domain = '';
        if (atIndex !== -1) {
            domain = emailValue.substring(atIndex + 1);
        }

        if (FREE_EMAIL_DOMAINS.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: report validity on all inputs
        const fullNameValid = fullNameInput.reportValidity();
        const emailValid = emailInput.reportValidity();
        const companyValid = companyInput.reportValidity();

        // Step 3: stop if any input is invalid
        if (!fullNameValid || !emailValid || !companyValid) {
            return;
        }

        // Step 4: call Apex
        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'success',
                    title: 'Registered'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'error',
                    title: 'Registration failed',
                    message: error.body.message
                })
            );
        }
    }
}
