import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    _label = '';
    _options = [];
    _value = '';
    _activeIndex = -1;

    @api
    get label() {
        return this._label;
    }
    set label(value) {
        this._label = value ?? '';
    }

    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        this._syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(value) {
        this._value = value ?? '';
        this._syncActiveIndex();
    }

    get listBoxLabel() {
        return this._label;
    }

    get activeDescendantId() {
        if (this._activeIndex >= 0 && this._activeIndex < this._options.length) {
            return this._optionId(this._activeIndex);
        }
        return '';
    }

    get renderedOptions() {
        return this._options.map((opt, index) => ({
            id: this._optionId(index),
            value: opt.value,
            label: opt.label,
            selected: opt.value === this._value,
            index
        }));
    }

    _optionId(index) {
        return `status-option-${index}`;
    }

    _indexForValue(val) {
        return this._options.findIndex((opt) => opt.value === val);
    }

    _syncActiveIndex() {
        const selectedIndex = this._indexForValue(this._value);
        if (selectedIndex >= 0) {
            this._activeIndex = selectedIndex;
        } else if (this._options.length > 0) {
            if (this._activeIndex < 0 || this._activeIndex >= this._options.length) {
                this._activeIndex = 0;
            }
        } else {
            this._activeIndex = -1;
        }
    }

    _selectIndex(index) {
        if (index < 0 || index >= this._options.length) {
            return;
        }
        const option = this._options[index];
        const alreadySelected = option.value === this._value;
        this._value = option.value;
        this._activeIndex = index;
        if (!alreadySelected) {
            this.dispatchEvent(
                new CustomEvent('change', {
                    detail: { value: option.value },
                    bubbles: true,
                    composed: true
                })
            );
        }
    }

    handleKeydown(event) {
        const key = event.key;
        const lastIndex = this._options.length - 1;
        if (lastIndex < 0) {
            return;
        }

        let nextIndex = null;

        switch (key) {
            case 'ArrowDown':
                nextIndex = Math.min(this._activeIndex + 1, lastIndex);
                break;
            case 'ArrowUp':
                nextIndex = Math.max(this._activeIndex - 1, 0);
                break;
            case 'Home':
                nextIndex = 0;
                break;
            case 'End':
                nextIndex = lastIndex;
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectIndex(this._activeIndex);
                return;
            default:
                return;
        }

        event.preventDefault();
        if (nextIndex !== null && nextIndex !== this._activeIndex && nextIndex >= 0) {
            this._activeIndex = nextIndex;
        }
    }

    handleOptionClick(event) {
        const li = event.currentTarget;
        const idx = Number(li.dataset.index);
        if (!Number.isNaN(idx)) {
            this._selectIndex(idx);
        }
    }
}
