public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final Integer LAST_DAY_SENTINEL = 31;

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> resultIds = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return resultIds;
        }

        // Validate all requests before any DML.
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];
            if (req == null) {
                throw new RecurringGiftException('Request at index ' + i + ' is null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('Request at index ' + i + ' has a null contact.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Request at index ' + i + ' has a null or non-positive amount.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > LAST_DAY_SENTINEL) {
                throw new RecurringGiftException('Request at index ' + i + ' has dayOfMonth outside 1-31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Request at index ' + i + ' has a null startDate.');
            }
        }

        List<npe03__Recurring_Donation__c> rds = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest req : requests) {
            Boolean openEnded = (req.installments == null || req.installments == 0);
            Boolean useLastDay = (req.dayOfMonth == LAST_DAY_SENTINEL);

            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();
            rd.npe03__Contact__c = req.contactId;
            rd.npe03__Amount__c = req.amount;
            rd.npe03__Installment_Period__c = 'Monthly';
            rd.npe03__Schedule_Type__c = 'Divide by N' ; // will be overwritten below
            rd.npe03__Date_Established__c = req.startDate;
            rd.npsp__RecurringType__c = 'True'; // (kept for NPSP's own processing)
            rd.npsp__InstallmentFrequency__c = 'Monthly';
            rd.npsp__Day_of_Month__c = useLastDay ? null : req.dayOfMonth;
            rd.npsp__Always_Use_Last_Day_Of_Month__c = useLastDay;
            rd.npsp__StartDate__c = req.startDate;
            rd.npsp__Status__c = 'Active';
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            if (openEnded) {
                rd.npe03__Open_Ended_Status__c = 'Open';
                rd.npe03__Schedule_Type__c = 'Constant Amount';
                rd.npsp__EndDate__c = null;
                rd.npe03__Installments__c = null;
            } else {
                rd.npe03__Open_Ended_Status__c = 'Closed';
                rd.npe03__Schedule_Type__c = 'Divide by N';
                rd.npe03__Installments__c = req.installments;
                rd.npsp__EndDate__c = null; // NPSP computes the end date from installments/frequency.
            }

            // Next payment date: first occurrence on/after startDate.
            rd.npe03__Next_Payment_Date__c = nextPaymentDate(req.startDate, req.dayOfMonth, useLastDay);

            rds.add(rd);
        }

        // Single DML statement; NPSP triggers generate the installment opportunities.
        insert rds;

        for (npe03__Recurring_Donation__c rd : rds) {
            resultIds.add(rd.Id);
        }
        return resultIds;
    }

    private static Date nextPaymentDate(Date startDate, Integer dayOfMonth, Boolean useLastDay) {
        if (useLastDay) {
            // Last day of the start month if startDate's day is already past in later months;
            // for the start month, if startDate is already the last day, use it.
            return lastDayOfMonth(startDate);
        }
        Integer startDay = startDate.day();
        if (startDay >= dayOfMonth) {
            return startDate;
        }
        Date candidate = Date.newInstance(startDate.year(), startDate.month(), dayOfMonth);
        return candidate;
    }

    private static Date lastDayOfMonth(Date d) {
        if (d.month() == 12) {
            return Date.newInstance(d.year(), 12, 31);
        }
        Date firstOfNext = Date.newInstance(d.year(), d.month() + 1, 1);
        return firstOfNext.addDays(-1);
    }
}
