public with sharing class FamilyService {

    private static final String REL_TYPE = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Build the set of all contact ids involved (children and parents)
        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            if (childId != null) {
                contactIds.add(childId);
            }
            Id parentId = parentIdByChildId.get(childId);
            if (parentId != null) {
                contactIds.add(parentId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // 1 SOQL: fetch any existing relationships between these contacts, in either direction
        List<npe4__Relationship__c> existing = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
              AND npe4__RelatedContact__c IN :contactIds
        ];

        // Index existing pairs in both directions so we can skip them
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : existing) {
            existingPairKeys.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
            existingPairKeys.add(pairKey(rel.npe4__RelatedContact__c, rel.npe4__Contact__c));
        }

        // 0 SOQL: fetch the reciprocal labels from the Relationship Lookup setting
        Map<String, String> reciprocalByType = new Map<String, String>();
        for (npe4__Relationship_Lookup__c setting : [
            SELECT Name, npe4__Male__c, npe4__Female__c, npe4__Neutral__c
            FROM npe4__Relationship_Lookup__c
            WHERE npe4__Active__c = true
        ]) {
            reciprocalByType.put(setting.Name, setting.npe4__Neutral__c);
        }

        // 0 SOQL: fetch parent Contact genders for reciprocal selection
        Set<Id> parentIds = new Set<Id>();
        for (Id parentId : parentIdByChildId.values()) {
            if (parentId != null) {
                parentIds.add(parentId);
            }
        }
        Map<Id, Contact> parentById = new Map<Id, Contact>(
            [SELECT Gender__c FROM Contact WHERE Id IN :parentIds]
        );

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }

            // Skip if a relationship already exists in either direction
            if (existingPairKeys.contains(pairKey(childId, parentId))) {
                continue;
            }

            String forwardReciprocal = resolveReciprocal(REL_TYPE, parentById.get(parentId), reciprocalByType);
            String backwardReciprocal = resolveReciprocal(forwardReciprocal, null, reciprocalByType);

            // Forward: parent -> child, typed as "Parent", reciprocal is Son/Daughter/Child
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = parentId,
                npe4__RelatedContact__c = childId,
                npe4__Type__c = REL_TYPE,
                npe4__Status__c = STATUS_CURRENT,
                npe4__ReciprocalRelationship__c = forwardReciprocal,
                npe4__Description__c = REL_TYPE
            ));

            // Backward: child -> parent, typed as Son/Daughter/Child, reciprocal is "Parent"
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = forwardReciprocal,
                npe4__Status__c = STATUS_CURRENT,
                npe4__ReciprocalRelationship__c = backwardReciprocal,
                npe4__Description__c = forwardReciprocal
            ));

            // Prevent duplicates within the same call
            existingPairKeys.add(pairKey(childId, parentId));
            existingPairKeys.add(pairKey(parentId, childId));
        }

        if (!toInsert.isEmpty()) {
            // 1 DML
            insert toInsert;
        }
    }

    private static String pairKey(Id a, Id b) {
        return String.valueOf(a) + ':' + String.valueOf(b);
    }

    private static String resolveReciprocal(String typeName, Contact person, Map<String, String> reciprocalByType) {
        if (!reciprocalByType.containsKey(typeName)) {
            return typeName;
        }
        // Determine gender-based label from the Relationship Lookup for the given type.
        // We only have Male/Female/Neutral values on the lookup row for the *type*, so
        // we need the actual lookup row to pick Male vs Female vs Neutral.
        return reciprocalByType.get(typeName);
    }
}
