```apex
public with sharing class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {
    @TestVisible
    private static Set<Id> idsToSync = new Set<Id>();
    @TestVisible
    private static Set<String> touchedSObjectTypes = new Set<String>();

    public void afterInsert(List<SObject> triggerNew) {
        collect(triggerNew);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<SObject> recordsNeedingSync = new List<SObject>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            SObject newRecord = triggerNew[i];
            SObject oldRecord = triggerOld[i];
            if (oldRecord != null && newRecord.get('StageName') != oldRecord.get('StageName')) {
                recordsNeedingSync.add(newRecord);
            }
        }
        collect(recordsNeedingSync);
    }

    private static void collect(List<SObject> records) {
        if (records == null || records.isEmpty()) {
            return;
        }
        if (!records.isEmpty()) {
            touchedSObjectTypes.add(String.valueOf(records[0].getSObjectType()));
        }
        for (SObject record : records) {
            idsToSync.add(record.Id);
        }
    }
}
