public with sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {
    public void execute(FinalizerHandler.Context context) {
        Set<Id> idsToSync = TA_Opportunity_CollectForErpSync.idsToSync;
        Boolean opportunityWasTouched = TA_Opportunity_CollectForErpSync.touchedSObjectTypes.contains('Opportunity');

        // Always reset the accumulator so the next DML operation starts clean,
        // regardless of which sObject this finalizer is being invoked for.
        TA_Opportunity_CollectForErpSync.idsToSync = new Set<Id>();
        TA_Opportunity_CollectForErpSync.touchedSObjectTypes = new Set<String>();

        if (opportunityWasTouched && !idsToSync.isEmpty()) {
            System.enqueueJob(new OpportunityErpSyncJob(idsToSync));
        }
    }
}
